-- Week 11 PostgreSQL disclosure queries.
SET client_encoding = 'UTF8';
SET search_path TO pevc_week11;

\copy (SELECT table_name, row_count FROM (SELECT 'week11_database_migration_plan' AS table_name, count(*)::text AS row_count FROM "week11_database_migration_plan" UNION ALL SELECT 'week11_persistent_db_readiness' AS table_name, count(*)::text AS row_count FROM "week11_persistent_db_readiness" UNION ALL SELECT 'week11_fund_deep_enrichment_queue' AS table_name, count(*)::text AS row_count FROM "week11_fund_deep_enrichment_queue" UNION ALL SELECT 'week11_manual_verification_template' AS table_name, count(*)::text AS row_count FROM "week11_manual_verification_template" UNION ALL SELECT 'week11_research_design_matrix' AS table_name, count(*)::text AS row_count FROM "week11_research_design_matrix" UNION ALL SELECT 'week11_variable_dictionary' AS table_name, count(*)::text AS row_count FROM "week11_variable_dictionary" UNION ALL SELECT 'week11_sample_expansion_plan' AS table_name, count(*)::text AS row_count FROM "week11_sample_expansion_plan" UNION ALL SELECT 'week11_quality_dashboard' AS table_name, count(*)::text AS row_count FROM "week11_quality_dashboard" UNION ALL SELECT 'week11_completion_checklist' AS table_name, count(*)::text AS row_count FROM "week11_completion_checklist" UNION ALL SELECT 'week11_manifest' AS table_name, count(*)::text AS row_count FROM "week11_manifest") q ORDER BY table_name) TO 'database/postgresql_week11_table_counts.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
\copy (SELECT '数据库类型' AS item, 'PostgreSQL临时实例/长期库脚本' AS value, 'Week11同时提供临时复现与长期库迁移脚本' AS source_note UNION ALL SELECT '临时库导入表数量', count(*)::text, 'pevc_week11 schema中的Week11派生表' FROM information_schema.tables WHERE table_schema = 'pevc_week11' UNION ALL SELECT '临时库导入总行数' AS item, sum(row_count)::text AS value, 'Week11派生表合计行数' AS source_note FROM (SELECT count(*) AS row_count FROM "week11_database_migration_plan" UNION ALL SELECT count(*) AS row_count FROM "week11_persistent_db_readiness" UNION ALL SELECT count(*) AS row_count FROM "week11_fund_deep_enrichment_queue" UNION ALL SELECT count(*) AS row_count FROM "week11_manual_verification_template" UNION ALL SELECT count(*) AS row_count FROM "week11_research_design_matrix" UNION ALL SELECT count(*) AS row_count FROM "week11_variable_dictionary" UNION ALL SELECT count(*) AS row_count FROM "week11_sample_expansion_plan" UNION ALL SELECT count(*) AS row_count FROM "week11_quality_dashboard" UNION ALL SELECT count(*) AS row_count FROM "week11_completion_checklist" UNION ALL SELECT count(*) AS row_count FROM "week11_manifest") s UNION ALL SELECT '基金深度核验队列数', count(*)::text, 'week11_fund_deep_enrichment_queue' FROM week11_fund_deep_enrichment_queue UNION ALL SELECT 'P1优先核验基金主体数', count(*)::text, 'manual_priority以P1开头' FROM week11_fund_deep_enrichment_queue WHERE manual_priority LIKE 'P1%' UNION ALL SELECT '备案编码/GP/LP已披露记录', count(*)::text, '只有任一深度字段非空才计数' FROM week11_fund_deep_enrichment_queue WHERE coalesce(amac_record_code,'') <> '' OR coalesce(gp_name,'') <> '' OR coalesce(lp_structure,'') <> '') TO 'database/postgresql_week11_disclosure.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8');
